let workflow={};try{workflow=JSON.parse(sessionStorage.getItem(VERSION)||'{}')}catch{}
let filter={query:'',industry:'all',status:'all'},tourStep=-1,drawerFocus=null;
const route=()=>{const a=location.hash.replace(/^#/,'').split('/');return {view:a[0]||'overview',id:a[1],tab:a[2]||'overview',finding:a[3]}};
const getMerchant=id=>merchants.find(m=>m.id===id)||merchants[0];
const stage=(m,f)=>workflow[m.id+':'+f]?.stage||0;
const isResolved=(m,f)=>stage(m,f)===4;
const issues=(m,area)=>m.findings.filter(f=>!isResolved(m,f)&&(!area||findings[f].area===area));
const allIssues=()=>merchants.flatMap(m=>issues(m).map(id=>({m,id,f:findings[id]})));
const total=(key)=>merchants.reduce((n,m)=>n+m[key],0);
const go=hash=>{if(location.hash==='#'+hash)render();else location.hash=hash};
const findingRoute=(m,f,tab='evidence')=>`merchant/${m.id}/${tab}/${f}`;
const button=(text,action,cls='')=>`<button class="button ${cls}" ${action}>${text}</button>`;
const title=(eyebrow,heading,sub,actions='')=>`<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="subtitle">${sub}</p></div><div class="title-actions">${actions}</div></div>`;
const sourceState=(s,m)=>{if(s.disabled)return ['Not enabled',''];if(m&&!s.policies.includes(m.policy))return ['Not applicable',''];let count=m?issues(m).filter(f=>f===s.key).length:allIssues().filter(x=>x.id===s.key).length;return count?[count+' for review','warn']:['No open signals','good']};
function sourcesHtml(m){return `<div class="sources">${['Sanctions & identity','Legal & regulatory','Reputation'].map(g=>`<div class="source-group"><h3>${g}</h3>${sources.filter(s=>s.group===g).map(s=>{const st=sourceState(s,m);return `<button class="source" data-source="${esc(s.name)}" data-merchant="${m?.id||''}"><span class="source-name"><span class="source-mark"></span>${s.name}</span>${tag(...st)}</button>`}).join('')}</div>`).join('')}</div><p class="fineprint">Source outcomes retain their context. A possible match is not a confirmed violation.</p>`}
function ribbon(m){return `<div class="policy-ribbon">${icon('shield')}<div><strong>Policy governs every check.</strong> <span>${m?esc(policies[m.policy].name)+' v'+policies[m.policy].version+' + screening baseline':merchants.length+' merchants assigned · 4 active policy versions'}</span></div><div class="mini-tags">${tag('Versioned','purple')}${tag('Traceable','purple')}</div><a class="button link right" href="#${m?'merchant/'+m.id+'/policies':'policies'}">View policies ${icon('arrow')}</a></div>`}
function domainCards(m){const prod=m?m.products:total('products'),review=m?m.reviewed:total('reviewed'),lic=m?m.licenses:total('licenses'),lr=m?m.licenseReview:total('licenseReview');const web=m?issues(m,'Website').length:allIssues().filter(x=>x.f.area==='Website').length;const mri=m?issues(m,'MRI').length:allIssues().filter(x=>x.f.area==='MRI').length;return `<div class="domain-grid">${[
 ['license','License validation',`${lic-lr}<span style="font-size:15px;color:#8795a4"> / ${lic}</span>`,'current license validations',`${lr} awaiting review`,'',Math.round((lic-lr)/lic*100),'License'],
 ['product','Product compliance',prod?Math.round(review/prod*100)+'%':'N/A',prod?'catalog products assessed':'not required by this policy',prod?fmt(prod)+' products · 6 check families':'Policy applicability preserved','green',prod?review/prod*100:0,'Product'],
 ['scan','Website compliance',web,'open website findings','Claims · disclosures · domain integrity','violet',web?78:100,'Website'],
 ['shield','Merchant risk intelligence',mri,'signals awaiting review','Sanctions · regulatory · reputation','amber',mri?70:100,'MRI']
 ].map(a=>`<button class="domain" data-domain="${a[7]}" data-merchant="${m?.id||''}"><div class="domain-top"><span class="icon-box ${a[5]}">${icon(a[0])}</span>${a[1]}</div><div class="domain-value">${a[2]}</div><div class="domain-label">${a[3]}</div>${a[7]==='License'||a[7]==='Product'?`<div class="track"><span style="width:${a[6]}%"></span></div>`:'<div style="height:26px"></div>'}<div class="domain-foot"><span>${a[4]}</span>${icon('arrow')}</div></button>`).join('')}</div>`}
function attention(m){let list=m?issues(m).map(id=>({m,id,f:findings[id]})):allIssues();list=list.sort((a,b)=>(a.f.severity==='High'?-1:1)-(b.f.severity==='High'?-1:1)).slice(0,3);return list.length?list.map(x=>`<div class="attention-item"><div class="attention-top"><h3>${x.f.title}</h3>${tag(x.f.severity,x.f.severity==='High'?'bad':'warn')}</div><p>${x.m.name} · ${x.f.area}</p><a class="button link" href="#${findingRoute(x.m,x.id)}">Review evidence ${icon('arrow')}</a></div>`).join(''):'<div class="empty">No open findings in this scope.</div>'}
function merchantTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>MERCHANT</th><th>LICENSES</th><th>PRODUCTS</th><th>WEBSITE</th><th>MRI</th><th>REVIEW STATUS</th><th></th></tr></thead><tbody>${list.map(m=>`<tr><td><a href="#merchant/${m.id}/overview" class="merchant-link"><span class="merchant-logo">${m.initials}</span><span>${m.name}<small>${m.industry} · ${m.state}</small></span></a></td><td>${tag(m.licenseReview?'Review':'Validated',m.licenseReview?'warn':'good')}</td><td>${m.products?fmt(m.products)+' products':'<span style="color:#98a3b0">Not applicable</span>'}</td><td>${tag(issues(m,'Website').length?issues(m,'Website').length+' findings':'No open findings',issues(m,'Website').length?'warn':'good')}</td><td>${tag(issues(m,'MRI').length?issues(m,'MRI').length+' signals':'No open signals',issues(m,'MRI').length?'warn':'good')}</td><td>${tag(issues(m).length?'Needs attention':'No open findings',issues(m).length?'warn':'good')}</td><td><a class="row-arrow" href="#merchant/${m.id}/overview" aria-label="Open ${m.name}">${icon('arrow')}</a></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No merchants match these filters.</td></tr>'}</tbody></table></div>`}
function overview(){const open=allIssues();return title('PORTFOLIO INTELLIGENCE','A clear view. A confident next step.','Your merchant portfolio, connected across every monitoring area.',`<a class="button" href="#reports">${icon('report')} Portfolio report</a>`)+`<section class="hero"><div><div class="eyebrow">ATLAS PAYMENTS · MERCHANT MONITORING</div><h2>See the signal.<br>Understand the whole merchant.</h2><p>Licenses, products, websites, and external intelligence—connected to your policies and a single review workflow.</p><div class="hero-brief"><a href="#merchant/greenfield/overview" class="button mint">Explore a merchant ${icon('arrow')}</a><span>Sample portfolio · Nov 5, 2026</span></div></div><div class="hero-numbers"><div class="hero-stat"><strong>${merchants.length}</strong><span>Merchants monitored</span><em>3 industry profiles</em></div><div class="hero-stat"><strong>${open.length}</strong><span>Open findings &amp; signals</span><em>${open.filter(x=>x.f.severity==='High').length} high priority</em></div><div class="hero-stat"><strong>100<span style="display:inline;font-size:21px">%</span></strong><span>Policy assignment</span><em>${merchants.length} of ${merchants.length} merchants</em></div></div></section>`+ribbon()+domainCards()+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Intelligence from every angle</h2><p>Named sources. Visible outcomes. Human review.</p></div>${tag('MRI','purple')}</div>${sourcesHtml()}</section><section class="panel"><div class="panel-head"><div><h2>Where to focus</h2><p>Priority findings across your portfolio.</p></div>${icon('spark')}</div>${attention()}</section></div><div class="section-title"><div><h2>Your merchant portfolio</h2><p>A shared view of each merchant’s monitoring posture.</p></div><a href="#merchants" class="button link">All ${merchants.length} merchants ${icon('arrow')}</a></div><section class="panel" style="padding:4px 8px">${merchantTable(merchants.slice(0,4),true)}</section>`}
function merchantsView(){const list=merchants.filter(m=>(m.name+' '+m.industry+' '+m.state).toLowerCase().includes(filter.query.toLowerCase())&&(filter.industry==='all'||m.industry===filter.industry)&&(filter.status==='all'||(filter.status==='attention'?issues(m).length>0:issues(m).length===0)));return title('PORTFOLIO','Every merchant, in context.','Search your book and open a merchant to follow the evidence.',button(icon('report')+' Export portfolio','data-export="portfolio"'))+`<section class="panel"><div class="filters"><label class="input-wrap">${icon('search')}<input id="merchant-search" aria-label="Search merchants" placeholder="Search merchants, industry, or state" value="${esc(filter.query)}"></label><select id="industry-filter" aria-label="Industry"><option value="all">All industries</option>${['Hemp / CBD','Online lending','Nutraceuticals'].map(i=>`<option ${filter.industry===i?'selected':''}>${i}</option>`).join('')}</select><select id="status-filter" aria-label="Review status"><option value="all">All review statuses</option><option value="attention" ${filter.status==='attention'?'selected':''}>Needs attention</option><option value="clear" ${filter.status==='clear'?'selected':''}>No open findings</option></select></div><div id="merchant-results">${merchantTable(list)}</div><p class="fineprint">${list.length} of ${merchants.length} sample merchants · Click a merchant to explore its complete monitoring record.</p></section>`}
function merchantShell(m,tab,content){return `<div class="title-row"><a class="button link" href="#merchants">${icon('back')} Back to portfolio</a><a href="#reports/${m.id}" class="button">${icon('report')} Merchant report</a></div><section class="merchant-hero"><span class="merchant-logo">${m.initials}</span><div><div class="eyebrow" style="color:#9cbec4">MERCHANT INTELLIGENCE</div><h1>${m.name}</h1><p>${m.industry} · ${m.state} · ${m.domain}</p><div class="mini-tags">${tag('Monitoring active','dark')}${tag('Policy assigned','dark')}</div></div><div class="merchant-hero-right">${tag(issues(m).length+' open findings & signals',issues(m).length?'warn':'good')}<small>Monitored since ${m.since}</small></div></section><nav class="tabs" aria-label="Merchant sections">${['overview','policies','evidence','remediation'].map(t=>`<a href="#merchant/${m.id}/${t}" class="${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}>${{overview:'Overview',policies:'Assigned policies',evidence:'Evidence & findings',remediation:'Remediation'}[t]}</a>`).join('')}</nav>${content}`}
function merchantOverview(m){return ribbon(m)+domainCards(m)+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Product compliance, beyond the document</h2><p>${m.products?'Composition, claims, labeling, and where products may be sold.':'Product and COA checks are excluded by this lending policy.'}</p></div></div>${m.products?`<div class="product-grid">${productChecks.map(c=>`<button class="check-tile" style="text-align:left;color:inherit" data-check="${c[3]}" data-merchant="${m.id}">${icon(c[0])}<h3>${c[1]}</h3><p>${c[2]}</p>${tag(m.findings.includes(c[3])&&!isResolved(m,c[3])?'Review finding':'View requirement',m.findings.includes(c[3])&&!isResolved(m,c[3])?'warn':'info')}</button>`).join('')}</div>`:'<div class="empty">Not applicable · consumer lending<br><small>Website disclosures, licenses, complaints, and identity screening remain in scope.</small></div>'}</section><section class="panel"><div class="panel-head"><div><h2>Merchant risk intelligence</h2><p>Applicability follows the assigned policy.</p></div></div>${sourcesHtml(m)}</section></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Findings requiring attention</h2><a class="button link" href="#merchant/${m.id}/evidence">All evidence ${icon('arrow')}</a></div>${attention(m)}</section><section class="panel"><div class="panel-head"><h2>A connected review record</h2>${icon('clock')}</div>${timeline(m)}</section></div>`}
function policyCards(keys,m){return `<div class="policy-cards">${keys.map(k=>{const p=policies[k];return `<article class="policy-card"><div class="coverage-head"><span class="policy-icon">${icon(p.icon)}</span>${tag('Active · v'+p.version,'good')}</div><h2>${p.name}</h2><p>${p.description}</p><div class="meta">${m?'Assigned to '+m.name:p.count+' merchants assigned'} · Published Oct 28, 2026</div><button class="button" data-policy="${k}">Inspect policy ${icon('arrow')}</button></article>`}).join('')}</div>`}
function policyView(m){return (m?'':title('POLICY CONTROL','Your rules. Applied consistently.','Versioned policies decide which checks run, what evidence is required, and how findings are reviewed.'))+policyCards(m?[m.policy,'screening']:Object.keys(policies),m)+`<div class="policy-flow"><span>Assign the policy</span><b>→</b><span>Run applicable checks</span><b>→</b><span>Collect evidence</span><b>→</b><span>Review &amp; remediate</span><b>→</b><span>Record the outcome</span></div><section class="panel"><div class="panel-head"><div><h2>Applicability is part of the answer</h2><p>A check that does not apply is never reported as a passed check.</p></div>${icon('policy')}</div><div class="table-wrap"><table><thead><tr><th>CHECK / SOURCE</th><th>HEMP / CBD</th><th>ONLINE LENDING</th><th>NUTRACEUTICALS</th></tr></thead><tbody>${[['License validation','Required','Required','Required'],['Product / lab / label checks','Required','Not applicable','Required'],['Website compliance','Required','Required','Required'],['FDA letters & recalls','Enabled','Not applicable','Enabled'],['CFPB complaints','Not applicable','Enabled','Not applicable'],['OFAC candidate screening','Enabled','Enabled','Enabled'],['BBB / Google / litigation','Enabled','Enabled','Enabled'],['PEP screening','Not enabled','Not enabled','Not enabled']].map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(v=>`<td>${tag(v,v==='Required'||v==='Enabled'?'good':'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function evidenceView(m,selected){const fId=m.findings.includes(selected)?selected:m.findings[0];if(!fId)return '<section class="panel empty"><h2>No open findings</h2><p>This merchant has no sample findings requiring review.</p><a href="#merchant/'+m.id+'/policies" class="button" style="margin-top:15px">Inspect assigned policies</a></section>';const f=findings[fId],s=stage(m,fId);return `<div class="evidence-layout"><div class="finding-list">${m.findings.map(id=>{const x=findings[id];return `<a class="finding ${id===fId?'active':''}" href="#${findingRoute(m,id)}"><div class="coverage-head">${tag(x.area,'info')}${tag(isResolved(m,id)?'Resolved':x.severity,isResolved(m,id)?'good':x.severity==='High'?'bad':'warn')}</div><h3>${x.title}</h3><p>${x.source}</p></a>`}).join('')}</div><section class="panel"><div class="evidence-title"><div><div class="eyebrow">EVIDENCE RECORD · DEMO-${m.id.toUpperCase().slice(0,3)}-${fId.toUpperCase()}</div><h2>${f.title}</h2></div>${tag(s===4?'Resolved':f.severity,s===4?'good':f.severity==='High'?'bad':'warn')}</div><p class="subtitle">${f.subject}</p><div class="evidence-quote"><small>Synthetic captured evidence</small>${esc(f.quote)}</div><div class="facts"><div><dt>Source</dt><dd>${f.source}</dd></div><div><dt>Captured</dt><dd>Nov 5, 2026 · 09:12 AM</dd></div><div><dt>Evidence reference</dt><dd>${f.evidence}</dd></div><div><dt>Merchant / source scope</dt><dd>${m.domain} · ${m.name}</dd></div></div><div class="requirement"><div class="eyebrow">GOVERNING POLICY · ${fId==='ofac'?'Merchant screening baseline v1.4':policies[m.policy].name+' v'+policies[m.policy].version}</div><p>${esc(f.rule)}</p></div><div class="button-row"><a class="button dark" href="#${findingRoute(m,fId,'remediation')}">${s===4?'View resolution':s?'Continue case':'Review & remediate'} ${icon('arrow')}</a><button class="button" data-policy="${fId==='ofac'?'screening':m.policy}">View policy</button></div><p class="fineprint">Synthetic evidence for this demo. No real merchant, external screening, or legal determination is represented.</p></section></div>`}
function timeline(m,fId){const base=[['09:12 AM','Monitoring evidence captured and linked to its policy.'],['09:14 AM','Finding routed to the processor’s review queue.']];const logs=Object.entries(workflow).filter(([k])=>k.startsWith(m.id+':')&&(!fId||k===m.id+':'+fId)).flatMap(([,v])=>v.log||[]);return `<div class="timeline">${[...base,...logs].map(e=>`<div class="timeline-item"><small>${esc(e[0])} · Demo activity</small><p>${esc(e[1])}</p></div>`).join('')}</div>`}
function remediation(m,selected){const fId=m.findings.includes(selected)?selected:m.findings[0];if(!fId)return '<section class="panel empty"><h2>No remediation required</h2><p>There are no sample cases for this merchant.</p></section>';const f=findings[fId],s=stage(m,fId),w=workflow[m.id+':'+fId]||{};const names=['Analyst review','Merchant request','Response received','Verified resolution'];let body='';if(s===0)body=`<h2>Review the evidence. Decide the next step.</h2><p>${fId==='ofac'?'This is a possible match, not a confirmed sanctions finding. Open an identity-review case to request clarification.':'Confirm that the captured evidence supports the policy finding before creating a remediation case.'}</p><div class="requirement"><p>${esc(f.rule)}</p></div><label class="field-label" for="case-note">Analyst rationale</label><textarea id="case-note">${fId==='ofac'?'Candidate name similarity requires identity clarification. No sanctions determination has been made.':'Reviewed the captured evidence against the assigned policy. Merchant correction and supporting evidence are required.'}</textarea>${button(fId==='ofac'?'Open identity-review case':'Confirm & open case','data-advance="1"','dark')}`;
if(s===1)body=`<h2>Send a clear remediation request.</h2><p>Case DEMO-${m.id.slice(0,3).toUpperCase()}-${fId.toUpperCase()} · Assigned to Alex Morgan</p><label class="field-label" for="case-note">Requested action</label><textarea id="case-note">${esc(f.action)}</textarea><div class="facts"><div><dt>Response due</dt><dd>November 12, 2026</dd></div><div><dt>Recipient</dt><dd>${m.name} · compliance contact</dd></div></div>${button('Send demo request','data-advance="2"','dark')}<p class="fineprint">Simulated delivery only. No email or external message is sent.</p>`;
if(s===2)body=`<h2>Waiting for the merchant’s response.</h2><p>The merchant receives the finding, requirement, evidence, and requested corrective action together.</p><div class="requirement"><div class="eyebrow">REQUEST SENT</div><p>${esc(w.request||f.action)}</p></div><label class="field-label" for="case-note">Simulated merchant response</label><textarea id="case-note">${fId==='potency'?'Affected batch GF-2408 has been removed from sale. Replacement batch GF-2410 is linked to sample report LAB-DEMO-051 (0.21%). Catalog and inventory evidence are attached.':fId==='ofac'?'Identity clarification supplied for the sample control person. Date of birth and jurisdiction differ from the candidate record. Please review the supporting identity attributes.':'The requested correction has been completed. Updated documentation and before/after evidence are provided for analyst review.'}</textarea>${button('Simulate merchant response','data-advance="3"','dark')}`;
if(s===3)body=`<h2>Verify the correction before closing.</h2><p>A merchant response stays open until the processor reviews the evidence.</p><div class="evidence-quote"><small>Merchant response · simulated</small>${esc(w.response)}</div><label class="field-label" for="case-note">Verification and outcome</label><textarea id="case-note">${fId==='ofac'?'Compared identity attributes and documented the differences. Candidate match dismissed as a false positive in this sample scenario.':'Verified the submitted correction and evidence against the assigned policy. This finding is resolved; the rest of the merchant’s monitoring remains active.'}</textarea><div class="button-row">${button(fId==='ofac'?'Dismiss match & close case':'Verify & resolve','data-advance="4"','dark')}${button('Request more evidence','data-advance="2"')}</div>`;
if(s===4)body=`<div class="icon-box green" style="margin-bottom:13px">${icon('check')}</div><h2>Resolved, with a complete record.</h2><p>${esc(w.resolution)}</p><div class="requirement"><div class="eyebrow">VERIFIED OUTCOME</div><p>Policy version, original evidence, merchant response, and reviewer rationale remain linked to this case.</p></div><div class="button-row"><a class="button dark" href="#reports/${m.id}">View merchant report ${icon('arrow')}</a><a class="button" href="#merchant/${m.id}/overview">Back to merchant</a></div>`;
return `<div class="panel-head"><div><h2>${f.title}</h2><p class="subtitle">${m.name} · ${f.area} · ${f.category}</p></div><a class="button" href="#${findingRoute(m,fId)}">View evidence</a></div><div class="steps">${names.map((n,i)=>`<div class="step ${s>i?'done':s===i?'current':''}"><span class="num">${s>i?'✓':i+1}</span><h3>${n}</h3><p>${['Processor verifies finding','Clear action & due date','Supporting evidence submitted','Processor records outcome'][i]}</p></div>`).join('')}</div><div class="two-col" style="margin-top:0"><section class="panel"><div class="workflow-card">${body}</div></section><section class="panel"><div class="panel-head"><h2>Case activity &amp; audit trail</h2>${icon('clock')}</div>${timeline(m,fId)}</section></div>`}
function monitoring(area='All'){const open=allIssues().filter(x=>area==='All'||x.f.area===area);return title('MONITORING COVERAGE','Every signal has a source.','Explore the check families and the evidence they contribute.')+`<nav class="tabs" aria-label="Monitoring areas">${['All','License','Product','Website','MRI'].map(a=>`<a href="#monitoring/${a}" class="${area===a?'active':''}">${a==='All'?'All areas':a==='License'?'Licenses':a==='MRI'?'Risk intelligence':a}</a>`).join('')}</nav>`+(area==='Product'?`<section class="panel"><h2>Product intelligence across six check families</h2><div class="product-grid">${productChecks.map(c=>`<button class="check-tile" style="text-align:left" data-check="${c[3]}">${icon(c[0])}<h3>${c[1]}</h3><p>${c[2]}</p>${tag('Explore requirement','info')}</button>`).join('')}</div></section>`:area==='MRI'?`<div class="source-detail-grid">${sources.map(s=>`<article class="source-card"><div class="coverage-head">${icon(s.icon)}${tag(...sourceState(s))}</div><h2 style="margin-top:14px">${s.name}</h2><p>${s.desc}</p><button class="button" data-source="${s.name}">Explore source ${icon('arrow')}</button></article>`).join('')}</div>`:domainCards())+`<div class="section-title"><div><h2>${area==='All'?'Portfolio':area} findings &amp; review signals</h2><p>${open.length} open records · Evidence and policy context included.</p></div></div><section class="panel">${findingsTable(open)}</section>`}
function findingsTable(list){return `<div class="table-wrap"><table><thead><tr><th>MERCHANT</th><th>AREA</th><th>FINDING / SIGNAL</th><th>PRIORITY</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${x.m.name}</td><td>${tag(x.f.area,'info')}</td><td>${x.f.title}<small style="display:block;color:var(--muted);font-size:9px">${x.f.source}</small></td><td>${tag(x.f.severity,x.f.severity==='High'?'bad':'warn')}</td><td><a class="button small" href="#${findingRoute(x.m,x.id)}">Review</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No open findings in this area.</td></tr>'}</tbody></table></div>`}
function casesView(){const opened=Object.entries(workflow).filter(([k,v])=>v.stage>0&&merchants.some(m=>k.startsWith(m.id+':')));return title('REMEDIATION','Close the loop, with evidence.','Track analyst review, merchant correction, and verified outcomes.')+`<div class="metric-row"><div class="metric"><small>Open cases</small><strong>${opened.filter(([,v])=>v.stage<4).length}</strong></div><div class="metric"><small>Awaiting merchant</small><strong>${opened.filter(([,v])=>v.stage===2).length}</strong></div><div class="metric"><small>Ready for verification</small><strong>${opened.filter(([,v])=>v.stage===3).length}</strong></div><div class="metric"><small>Verified resolutions</small><strong>${opened.filter(([,v])=>v.stage===4).length}</strong></div></div><section class="panel">${opened.length?`<div class="table-wrap"><table><thead><tr><th>MERCHANT</th><th>CASE</th><th>STATUS</th><th></th></tr></thead><tbody>${opened.map(([key,w])=>{const[mid,id]=key.split(':'),m=getMerchant(mid);return `<tr><td>${m.name}</td><td>${findings[id].title}</td><td>${tag(['','Request prepared','Awaiting merchant','Response received','Resolved'][w.stage],w.stage===4?'good':'warn')}</td><td><a class="button small" href="#${findingRoute(m,id,'remediation')}">Open case</a></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><div class="icon-box" style="margin:0 auto 15px">${icon('case')}</div><h2>Your review queue is ready.</h2><p class="subtitle">Open a finding and create the first sample remediation case.</p><a class="button dark" style="margin-top:17px" href="#merchant/greenfield/remediation/potency">Start the product compliance case ${icon('arrow')}</a></div>`}</section>`}
function reports(m){const list=m?issues(m).map(id=>({m,id,f:findings[id]})):allIssues(),resolved=Object.keys(workflow).filter(k=>workflow[k].stage===4&&(!m||k.startsWith(m.id+':'))).length;return title('REPORTING','The complete story, ready to share.','A traceable summary of monitoring coverage, findings, and verified action.',button(icon('report')+' Print / save PDF','data-print="true"'))+`<section class="report-banner"><div><div class="eyebrow" style="color:#a6c6d2">SAMPLE MONITORING REPORT</div><h2>${m?m.name:'Atlas Payments · Portfolio summary'}</h2><p>As of November 5, 2026 · Versioned policy + evidence + outcomes</p></div>${button('Export findings CSV','data-export="findings"','mint')}</section><div class="report-grid"><section class="report-sheet"><div class="eyebrow">COVERAGE &amp; ACCOUNTABILITY</div><h2>${m?'Merchant':'Portfolio'} monitoring</h2><div class="report-line"></div>${[['Merchants in scope',m?1:merchants.length],['Active policy versions',m?2:4],['Products in catalog',fmt(m?m.products:total('products'))],['Open findings & signals',list.length],['High-priority findings',list.filter(x=>x.f.severity==='High').length],['Verified resolutions this session',resolved]].map(r=>`<div class="report-item"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}<p class="fineprint">Sample data. Resolved findings do not imply that the whole merchant is compliant. PEP screening is not enabled in this scenario.</p></section><section class="panel"><div class="panel-head"><div><h2>Policy and evidence provenance</h2><p>Every outcome keeps its supporting context.</p></div>${icon('policy')}</div>${(m?[m.policy,'screening']:Object.keys(policies)).map(k=>`<div class="attention-item"><div class="attention-top"><h3>${policies[k].name}</h3>${tag('v'+policies[k].version,'purple')}</div><p>Assigned policy version retained with findings and case history.</p><button class="button link" data-policy="${k}">Inspect policy ${icon('arrow')}</button></div>`).join('')}</section></div><div class="section-title"><h2>Open findings &amp; signals</h2></div><section class="panel">${findingsTable(list)}</section>${resolved?`<div class="section-title"><h2>Verified resolutions</h2></div><section class="panel">${Object.entries(workflow).filter(([k,w])=>w.stage===4&&(!m||k.startsWith(m.id+':'))).map(([k,w])=>{const[mid,id]=k.split(':');return `<div class="attention-item"><div class="attention-top"><h3>${getMerchant(mid).name} · ${findings[id].title}</h3>${tag('Resolved','good')}</div><p>${esc(w.resolution)}</p><a href="#${findingRoute(getMerchant(mid),id,'remediation')}" class="button link">View audit trail ${icon('arrow')}</a></div>`}).join('')}</section>`:''}`}
function render(){closeDrawer();const r=route(),m=getMerchant(r.id);let html='';if(r.view==='overview')html=overview();else if(r.view==='merchants')html=merchantsView();else if(r.view==='merchant')html=merchantShell(m,r.tab,r.tab==='policies'?policyView(m):r.tab==='evidence'?evidenceView(m,r.finding):r.tab==='remediation'?remediation(m,r.finding):merchantOverview(m));else if(r.view==='policies')html=policyView();else if(r.view==='monitoring')html=monitoring(['All','License','Product','Website','MRI'].includes(r.id)?r.id:'All');else if(r.view==='cases')html=casesView();else if(r.view==='reports')html=reports(r.id?m:null);else html=overview();$('#content').innerHTML=html;const active=r.view==='merchant'?'merchants':r.view;$('#navigation').innerHTML=[['overview','grid','Overview'],['merchants','building','Merchants'],['monitoring','scan','Monitoring'],['policies','policy','Policies'],['cases','case','Cases'],['reports','report','Reports']].map(a=>`<a href="#${a[0]}" class="${active===a[0]?'active':''}" ${active===a[0]?'aria-current="page"':''} aria-label="${a[2]}">${icon(a[1])}<span>${a[2]}</span></a>`).join('');$('#breadcrumb').innerHTML='Atlas Payments <span>/</span> '+esc(r.view==='merchant'?m.name:r.view.charAt(0).toUpperCase()+r.view.slice(1));bindFilters();renderTour();document.title=(r.view==='merchant'?m.name:'Qredible')+' · Merchant Monitoring';}
function bindFilters(){const q=$('#merchant-search');if(q)q.addEventListener('input',e=>{filter.query=e.target.value;updateMerchantResults()});for(const[id,key]of[['industry-filter','industry'],['status-filter','status']]){const el=$('#'+id);if(el)el.addEventListener('change',e=>{filter[key]=e.target.value;updateMerchantResults()})}}
function updateMerchantResults(){const current=document.createElement('div');current.innerHTML=merchantsView();$('#merchant-results').innerHTML=current.querySelector('#merchant-results').innerHTML;$('#merchant-results').nextElementSibling.textContent=current.querySelector('#merchant-results').nextElementSibling.textContent;}
function showDrawer(title,body){drawerFocus=document.activeElement;$('#drawer-title')?.remove();$('#drawer').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">QREDIBLE · DEMO DETAIL</div><h2 id="drawer-title">${esc(title)}</h2></div><button class="close" aria-label="Close detail" data-close="true">×</button></div>${body}`;$('#drawer').hidden=false;$('#drawer-backdrop').hidden=false;document.body.style.overflow='hidden';$('#drawer .close').focus()}
function closeDrawer(){if(!$('#drawer'))return;const was=!$('#drawer').hidden;$('#drawer').hidden=true;$('#drawer-backdrop').hidden=true;document.body.style.overflow='';if(was&&drawerFocus?.isConnected)drawerFocus.focus()}
function showPolicy(k){const p=policies[k];if(!p)return;showDrawer(p.name,`${tag('Active · v'+p.version,'good')}<p style="margin:15px 0">${p.description}</p><div class="requirement"><div class="eyebrow">VERSIONED POLICY CONTRACT</div><p>Published Oct 28, 2026 · Owner: Atlas compliance team · Prior version retained for audit history.</p></div><div class="section-title"><h2>Checks governed by this policy</h2></div><ul>${p.checks.map(c=>`<li>${c}</li>`).join('')}</ul><div class="section-title"><h2>Evidence &amp; review</h2></div><p>Each result retains its policy version, source reference, capture time, and review status. A confirmed finding opens the remediation workflow; unresolved source matches stay in analyst review.</p><div class="section-title"><h2>Intelligence sources</h2></div><div class="mini-tags">${p.sources.map(s=>tag(s,'info')).join('')}</div><p class="fineprint">Illustrative policy configuration. Thresholds and requirements shown here demonstrate the workflow; they are not a legal interpretation.</p>`)}
function showSource(name,mid){const s=sources.find(x=>x.name===name);if(!s)return;const m=mid?getMerchant(mid):null,st=sourceState(s,m);const matching=(m?issues(m).map(id=>({m,id,f:findings[id]})):allIssues()).filter(x=>x.id===s.key);showDrawer(name,`${tag(...st)}<p style="margin:15px 0">${s.desc}</p><div class="facts"><div><dt>Scope</dt><dd>${m?m.name:'Atlas Payments portfolio'}</dd></div><div><dt>Refresh model</dt><dd>${s.disabled?'Source not enabled':'Cadence defined by policy'}</dd></div></div><div class="requirement"><div class="eyebrow">POLICY APPLICABILITY</div><p>${s.disabled?'PEP is shown as an available source that is not enabled in this demo. It does not contribute a pass, failure, or completed screening.':m&&!s.policies.includes(m.policy)?'This source does not apply to the selected merchant’s policy. No pass or failure is inferred.':'Source records require entity matching, freshness checks, and contextual analyst review.'}</p></div><div class="section-title"><h2>${matching.length?'Linked evidence':'Current outcome'}</h2></div>${matching.length?matching.map(x=>`<div class="attention-item"><h3>${x.m.name}</h3><p>${x.f.title}</p><a class="button dark" href="#${findingRoute(x.m,x.id)}">Review evidence ${icon('arrow')}</a></div>`).join(''):`<p>${s.disabled?'Source enablement is required before screening can run.':st[0]==='Not applicable'?'Excluded by policy applicability.':'No open sample signals in this scope. This is not a general compliance determination.'}</p>`}`)}
function showCheck(id,mid){const m=mid?getMerchant(mid):merchants.find(m=>m.findings.includes(id));if(m&&m.findings.includes(id)){go(findingRoute(m,id));return}const c=productChecks.find(x=>x[3]===id),f=findings[id];showDrawer(c?.[1]||'Product check',`<p>${c?.[2]||''}</p><div class="requirement" style="margin-top:20px"><div class="eyebrow">SAMPLE POLICY REQUIREMENT</div><p>${esc(f.rule)}</p></div><div class="section-title"><h2>Evidence to retain</h2></div><p>${esc(f.evidence)}</p><div class="section-title"><h2>When a finding is confirmed</h2></div><p>${esc(f.action)}</p><p class="fineprint">This merchant has no sample finding for this check. The requirement remains visible as part of its monitoring coverage.</p>`)}
function advance(next){const r=route(),m=getMerchant(r.id),fId=m.findings.includes(r.finding)?r.finding:m.findings[0];if(!fId)return;const key=m.id+':'+fId,prev=workflow[key]||{stage:0,log:[]},note=$('#case-note')?.value.trim();if(!note){toast('Add a review note before continuing.');$('#case-note')?.focus();return}const allowed={0:[1],1:[2],2:[3],3:[2,4],4:[]};if(!allowed[prev.stage].includes(next))return;const fields={1:'rationale',2:'request',3:'response',4:'resolution'};const labels={1:'Analyst opened a case with documented rationale.',2:prev.stage===3?'Analyst requested additional evidence.':'Remediation request sent in the demo.',3:'Merchant response and sample evidence received.',4:'Processor verified and recorded the resolution.'};workflow[key]={...prev,stage:next,[fields[next]]:note,log:[...(prev.log||[]),[new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),labels[next]]]};try{sessionStorage.setItem(VERSION,JSON.stringify(workflow))}catch{}render();toast(next===4?'Case resolved. Portfolio and report updated.':labels[next]);}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
const tour=[['See the portfolio','Start with coverage across licenses, products, websites, and merchant risk intelligence.','overview'],['Understand one merchant','Greenfield shows how every monitoring area contributes to one merchant record.','merchant/greenfield/overview'],['Show the governing policy','Open a policy to see the versioned checks, source applicability, and review requirements.','merchant/greenfield/policies'],['Connect the signal to evidence','This product exceeds a configured lab limit. The finding keeps the batch, evidence, and policy together.','merchant/greenfield/evidence/potency'],['Close the loop','Use the case actions: confirm → send demo request → simulate response → verify and resolve.','merchant/greenfield/remediation/potency'],['Show the outcome','The report reflects your session’s resolution, with evidence and policy provenance retained.','reports/greenfield']];
function renderTour(){const el=$('#tour');if(tourStep<0){el.hidden=true;return}el.hidden=false;const t=tour[tourStep];el.innerHTML=`<span class="tour-count">${tourStep+1}/6</span><div><h3>${t[0]}</h3><p>${t[1]}</p></div><div class="tour-actions">${tourStep?button('Back','data-tour="back"','small'):''}${button(tourStep===5?'Finish tour':'Next','data-tour="next"','dark small')}${button('Exit','data-tour="exit"','subtle small')}</div>`}
function runTour(step){tourStep=step;if(step>=tour.length){tourStep=-1;renderTour();toast('Walkthrough complete. Continue exploring or reset the demo.');return}go(tour[step][2]);renderTour();window.scrollTo({top:0,behavior:'smooth'})}
function downloadCSV(type){const r=route(),m=(r.view==='merchant'||r.view==='reports')&&r.id?getMerchant(r.id):null;let rows;if(type==='portfolio')rows=[['Merchant','Industry','State','Licenses','Products','Open findings','Policy'],...merchants.map(m=>[m.name,m.industry,m.state,m.licenses,m.products,issues(m).length,policies[m.policy].name])];else rows=[['Merchant','Area','Finding','Priority','Source','Policy version','Status'],...(m?[m]:merchants).flatMap(m=>m.findings.map(id=>[m.name,findings[id].area,findings[id].title,findings[id].severity,findings[id].source,id==='ofac'?'Screening v1.4':policies[m.policy].name+' v'+policies[m.policy].version,isResolved(m,id)?'Resolved':'Open']))];rows.push(['Illustrative demo data; no live screenings or real merchant findings.']);const csv=rows.map(row=>row.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='qredible-demo-'+type+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample CSV exported.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.policy)showPolicy(b.dataset.policy);else if(b.dataset.source)showSource(b.dataset.source,b.dataset.merchant);else if(b.dataset.check)showCheck(b.dataset.check,b.dataset.merchant);else if(b.dataset.domain){const m=b.dataset.merchant?getMerchant(b.dataset.merchant):null;if(m){const id=issues(m,b.dataset.domain)[0];if(id)go(findingRoute(m,id));else showDrawer(b.dataset.domain+' monitoring',`<p>${b.dataset.domain==='Product'&&!m.products?'Product and COA checks do not apply to this lending policy.':'No open sample findings in this monitoring area. Review the assigned policy for the applicable requirements.'}</p><div class="button-row"><a class="button" href="#merchant/${m.id}/policies">View assigned policies</a></div>`)}else go('monitoring/'+b.dataset.domain)}else if(b.dataset.advance)advance(Number(b.dataset.advance));else if(b.dataset.close)closeDrawer();else if(b.dataset.export)downloadCSV(b.dataset.export);else if(b.dataset.print)window.print();else if(b.dataset.tour==='next')runTour(tourStep+1);else if(b.dataset.tour==='back')runTour(tourStep-1);else if(b.dataset.tour==='exit'){tourStep=-1;renderTour()}else if(b.id==='start-tour')runTour(0);else if(b.id==='reset-demo'){showDrawer('Reset this demo?',`<p>This clears the sample cases and reviewer notes from this browser session, returning every finding to its starting state.</p><div class="button-row">${button('Reset sample workflow','data-reset-confirm="true"','dark')}${button('Keep exploring','data-close="true"')}</div>`)}else if(b.dataset.resetConfirm){workflow={};try{sessionStorage.removeItem(VERSION)}catch{}tourStep=-1;filter={query:'',industry:'all',status:'all'};go('overview');render();toast('Demo reset to its starting state.')}});
$('#drawer-backdrop').addEventListener('click',closeDrawer);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&!$('#drawer').hidden){const els=[...$('#drawer').querySelectorAll('button,a[href],input,textarea,select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
render();
